const DT=1/60;
class Duel{
 constructor(seed='DOWN-001',swap=false){this.seed=seed;this.rng=2166136261;for(const c of String(seed))this.rng=Math.imul(this.rng^c.charCodeAt(0),16777619)>>>0;this.tick=0;this.events=[];this.shots=[];this.result=null;this.fighters=['goku','vegeta'].map((id,i)=>({id,name:i?'VEGETA':'SON GOKU',x:(i^Number(swap))?730:230,y:270,hp:1200,max:1200,face:(i^Number(swap))?-1:1,state:'idle',age:0,cd:0,beamCd:.55+i*.2,dashCd:0,hit:false,damage:0,dodges:0,beams:0,combo:0,moveX:0,moveY:0,actionX:0,actionY:0,choice:this.rand(),think:0}));}
 rand(){let x=this.rng;x^=x<<13;x^=x>>>17;x^=x<<5;this.rng=x>>>0;return this.rng/4294967296;}
 event(type,f,extra={}){this.events.push({tick:this.tick,type,id:f.id,...extra});}
 act(f,state,tx,ty){f.state=state;f.age=0;f.hit=false;const d=Math.hypot(tx,ty)||1;f.actionX=tx/d;f.actionY=ty/d;if(Math.abs(tx)>0.1)f.face=Math.sign(tx);if(state==='melee')f.cd=.6+this.rand()*.16;if(state==='beam'){f.beamCd=5.5+this.rand()*1.5;f.beams++;}if(state==='dash'){f.dashCd=3.2;f.dodges++;}this.event(state,f);}
 step(){if(this.result)return;this.tick++;const hits=[];
 for(let i=0;i<2;i++){const f=this.fighters[i],o=this.fighters[1-i];f.age+=DT;for(const k of ['cd','beamCd','dashCd'])f[k]=Math.max(0,f[k]-DT);const dx=o.x-f.x,dy=o.y-f.y,d=Math.hypot(dx,dy)||1;
 if(f.state==='dash'){f.x+=f.actionX*650*DT;f.y+=f.actionY*650*DT;if(f.age>=.23){f.state='idle';f.age=0;}}
 else if(f.state==='melee'){if(f.age>=.23&&!f.hit){f.hit=true;const dot=(dx*f.actionX+dy*f.actionY)/d;if(d<98&&dot>.35)hits.push({target:o,source:f,value:76});else this.event('miss',f);}if(f.age>=.57){f.state='idle';f.age=0;}}
 else if(f.state==='beam'){if(f.age>=.65&&!f.hit){f.hit=true;this.shots.push({id:f.id,x:f.x+f.actionX*35,y:f.y+f.actionY*35,vx:f.actionX*570,vy:f.actionY*570,life:1.8});this.event('fire',f);}if(f.age>=1.05){f.state='idle';f.age=0;}}
 else {f.think-=DT;if(f.think<=0){f.think=.10;f.choice=this.rand();let danger=false;
 if(o.state==='beam'&&o.age>.18&&o.age<.78){const px=f.x-o.x,py=f.y-o.y;danger=px*o.actionX+py*o.actionY>0&&Math.abs(px*o.actionY-py*o.actionX)<50;}
 if(o.state==='melee'&&o.age>.18&&o.age<.3&&d<100)danger=true;
 for(const s of this.shots)if(s.id!==f.id){const sx=f.x-s.x,sy=f.y-s.y;const speed=Math.hypot(s.vx,s.vy);if((sx*s.vx+sy*s.vy)/speed>0&&(sx*s.vx+sy*s.vy)/speed<160&&Math.abs(sx*s.vy-sy*s.vx)/speed<45)danger=true;}
 if(danger&&f.dashCd===0){let ex=-dy/d,ey=dx/d;if(f.y+ey*120>485||f.y+ey*120<60){ex=-ex;ey=-ey;}this.act(f,'dash',ex,ey);}
 else if(f.beamCd===0&&d>105&&d<550)this.act(f,'beam',dx,dy);
 else if(d<83&&f.cd===0)this.act(f,'melee',dx,dy);
 else{f.moveX=d>76?dx/d:0;f.moveY=d>76?dy/d:0;if(d<125&&f.cd>.1){f.moveX=-dx/d*.55;f.moveY=-dy/d*.55;}if(f.beamCd<.7&&d<190){f.moveX=-dx/d;f.moveY=-dy/d;}if(d>130){const side=f.choice>.5?1:-1;f.moveX+=-dy/d*.25*side;f.moveY+=dx/d*.25*side;}f.state=Math.abs(f.moveX)+Math.abs(f.moveY)>.1?'run':'idle';}}
 if(f.state==='run'){f.x+=f.moveX*175*DT;f.y+=f.moveY*175*DT;}if(['idle','run'].includes(f.state)&&Math.abs(dx)>.1)f.face=Math.sign(dx);}
 f.x=Math.max(40,Math.min(920,f.x));f.y=Math.max(65,Math.min(490,f.y));}
 const [a,b]=this.fighters;let dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy);if(d<42){if(!d){dx=1;dy=0;d=1;}const p=(42-d)/2;a.x-=dx/d*p;a.y-=dy/d*p;b.x+=dx/d*p;b.y+=dy/d*p;}
 for(const f of this.fighters){f.x=Math.max(40,Math.min(920,f.x));f.y=Math.max(65,Math.min(490,f.y));}
 for(const s of this.shots){const ox=s.x,oy=s.y;s.x+=s.vx*DT;s.y+=s.vy*DT;s.life-=DT;const target=this.fighters.find(f=>f.id!==s.id),vx=s.x-ox,vy=s.y-oy,t=Math.max(0,Math.min(1,((target.x-ox)*vx+(target.y-oy)*vy)/(vx*vx+vy*vy)));if(Math.hypot(target.x-ox-t*vx,target.y-oy-t*vy)<34){hits.push({target,source:this.fighters.find(f=>f.id===s.id),value:230});s.life=0;}}
 this.shots=this.shots.filter(s=>s.life>0&&s.x>-60&&s.x<1020&&s.y>-60&&s.y<600);
 for(const h of hits){h.target.hp-=h.value;h.source.damage+=h.value;this.event('hit',h.target,{value:h.value,source:h.source.id,x:h.target.x,y:h.target.y});}
 for(const f of this.fighters)f.hp=Math.max(0,f.hp);
 if(this.fighters.some(f=>!f.hp)||this.tick>=3600){this.result=a.hp===b.hp?'draw':a.hp>b.hp?a.id:b.id;for(const f of this.fighters)if(!f.hp){f.state='defeat';f.age=0;}this.event('end',a,{winner:this.result});}}
}

class ArenaAudio {
 constructor(){this.ctx=null;this.muted=false;this.volume=.28;this.lastHit=-1;}
 unlock(){if(!this.ctx){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;this.ctx=new AC();this.master=this.ctx.createGain();this.master.gain.value=this.volume;this.compressor=this.ctx.createDynamicsCompressor();this.master.connect(this.compressor);this.compressor.connect(this.ctx.destination);}if(this.ctx.state==='suspended')this.ctx.resume().catch(()=>{});}
 setMuted(value){this.muted=value;if(this.master)this.master.gain.setTargetAtTime(value?0:this.volume,this.ctx.currentTime,.025);}
 setVolume(value){this.volume=Number(value);if(this.master)this.master.gain.setTargetAtTime(this.muted?0:this.volume,this.ctx.currentTime,.025);}
 tone(freq,end,duration,type='sine',gain=.2,delay=0){if(!this.ctx||this.ctx.state!=='running'||this.muted)return;const t=this.ctx.currentTime+delay,o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);o.frequency.exponentialRampToValueAtTime(Math.max(20,end),t+duration);g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(gain,t+.012);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g);g.connect(this.master);o.start(t);o.stop(t+duration+.03);}
 noise(duration,gain=.3,cutoff=1200){if(!this.ctx||this.ctx.state!=='running'||this.muted)return;const t=this.ctx.currentTime,buffer=this.ctx.createBuffer(1,Math.ceil(this.ctx.sampleRate*duration),this.ctx.sampleRate),data=buffer.getChannelData(0);let seed=7919;for(let i=0;i<data.length;i++){seed=(Math.imul(seed,1664525)+1013904223)>>>0;data[i]=(seed/4294967296*2-1)*(1-i/data.length);}const src=this.ctx.createBufferSource(),filter=this.ctx.createBiquadFilter(),g=this.ctx.createGain();src.buffer=buffer;filter.type='lowpass';filter.frequency.value=cutoff;g.gain.setValueAtTime(gain,t);g.gain.exponentialRampToValueAtTime(.001,t+duration);src.connect(filter);filter.connect(g);g.connect(this.master);src.start();}
 play(type,heavy=false){switch(type){case 'melee':this.noise(.1,.2,2100);break;case 'dash':this.noise(.22,.17,3500);this.tone(700,180,.18,'sine',.05);break;case 'beam':this.tone(130,740,.6,'triangle',.13);this.tone(200,1000,.6,'sine',.07);break;case 'fire':this.noise(.45,.3,2300);this.tone(420,70,.4,'sawtooth',.09);break;case 'hit':if(this.ctx&&this.ctx.currentTime-this.lastHit>.07){this.lastHit=this.ctx.currentTime;this.noise(heavy?.24:.12,heavy?.42:.25,heavy?800:1700);this.tone(heavy?110:190,35,.18,'triangle',.3);}break;case 'end':this.tone(262,262,.25,'triangle',.18);this.tone(330,330,.25,'triangle',.18,.18);this.tone(392,392,.6,'triangle',.18,.36);break;}}
}

const EMBEDDED={"goku": "data:image/png;base64,", "vegeta": "data:image/png;base64,"};


const audio=new ArenaAudio();let hitFlash={},shake=0,resultAge=0,resultShown=false,particles=[],ghosts=[],bursts=[],visualClock=0;
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d');let duel=new Duel(),running=false,started=false,swap=false,acc=0,last=0,seen=0,fx=[],images={};
$('sound').onclick=()=>{audio.unlock();audio.setMuted(!audio.muted);$('sound').textContent=audio.muted?'♪ Âm thanh tắt':'♪ Âm thanh bật';$('sound').setAttribute('aria-pressed',String(audio.muted));};$('volume').oninput=e=>audio.setVolume(e.target.value);
for(const id of ['goku','vegeta']){const im=new Image();im.src=EMBEDDED[id];images[id]=im;}
const names={goku:'Goku',vegeta:'Vegeta'},rows={idle:0,run:1,melee:2,dash:3,beam:4,powerup:5,hurt:6,defeat:7};
function reset(){duel=new Duel($('seed').value||'DOWN-001',swap);running=false;started=false;acc=0;seen=0;fx=[];hitFlash={};particles=[];ghosts=[];bursts=[];visualClock=0;shake=0;resultAge=0;resultShown=false;$('overlay').classList.remove('result');$('overlay').style.display='flex';$('overlay').innerHTML='<span class="eyebrow">TRẬN ĐẤU ĐÃ SẴN SÀNG</span><h2>GOKU <i>vs</i> VEGETA</h2><p>Di chuyển · Cận chiến · Lướt né · Tung chưởng</p><button id="heroStart">Bắt đầu trận ↗</button>';$('heroStart').onclick=toggle;$('start').textContent='▶ Bắt đầu';$('log').textContent='Khởi động trận để theo dõi các pha giao đấu.';$('seedLabel').textContent='SEED: '+duel.seed;update();}
function toggle(){audio.unlock();if(duel.result)reset();running=!running;started=true;$('overlay').style.display='none';$('start').textContent=running?'Ⅱ Tạm dừng':'▶ Tiếp tục';$('status').textContent=running?'ĐANG GIAO ĐẤU':'TẠM DỪNG';acc=0;}
$('start').onclick=toggle;$('heroStart').onclick=toggle;$('reset').onclick=reset;$('swap').onclick=()=>{swap=!swap;reset();};$('seed').onchange=reset;$('record').onclick=()=>{document.body.classList.toggle('cinema');$('record').textContent=document.body.classList.contains('cinema')?'↙ Thoát chế độ quay':'⛶ Chế độ quay';};document.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','SELECT','BUTTON'].includes(document.activeElement.tagName)){e.preventDefault();toggle();}if(e.code==='Escape')document.body.classList.remove('cinema');});document.addEventListener('visibilitychange',()=>{if(document.hidden&&running)toggle();});
function update(){for(let i=0;i<2;i++){const f=duel.fighters[i];$('hp'+i).textContent=`${f.hp} / ${f.max}`;$('bar'+i).style.width=f.hp/f.max*100+'%';$('cd'+i).textContent=(i?'GALICK GUN':'KAMEHAMEHA')+' · '+(f.beamCd>0?f.beamCd.toFixed(1)+'s':'SẴN SÀNG');}$('clock').textContent=Math.max(0,60-duel.tick*DT).toFixed(1);}
function events(){while(seen<duel.events.length){const e=duel.events[seen++];audio.play(e.type,e.value>=200);
 if(e.type==='hit'){bursts.push({x:e.x,y:e.y-28,id:e.source,heavy:e.value>=200,life:e.value>=200?.46:.24,max:e.value>=200?.46:.24});fx.push({...e,life:.65});hitFlash[e.id]=.18;shake=e.value>=200?7:3;for(let k=0;k<12;k++){const angle=k*Math.PI/6+e.tick*.1;particles.push({x:e.x,y:e.y-28,vx:Math.cos(angle)*(75+k*7),vy:Math.sin(angle)*(75+k*7),life:.32,max:.32,color:e.source==='goku'?'#a4ecff':'#dfb5ff'});}}
if(!['hit','fire','end'].includes(e.type))continue;let msg=e.type==='hit'?`${names[e.source]} đánh trúng ${names[e.id]} · −${e.value} HP`:e.type==='fire'?`${names[e.id]} tung ${e.id==='goku'?'Kamehameha':'Galick Gun'}`:'Trận đấu kết thúc';const line=document.createElement('div'),time=document.createElement('time');time.textContent=(e.tick*DT).toFixed(1)+'s';line.append(time,document.createTextNode(msg));if(!$('log').children.length)$('log').textContent='';$('log').prepend(line);while($('log').children.length>40)$('log').lastChild.remove();}
 if(duel.result&&running){running=false;resultAge=0;$('status').textContent='KẾT LIỄU';}if(duel.result&&resultAge>1.15&&!resultShown){resultShown=true;$('overlay').classList.add('result');$('start').textContent='▶ Trận mới';$('status').textContent='ĐÃ KẾT THÚC';const title=duel.result==='draw'?'TRẬN ĐẤU HÒA':names[duel.result].toUpperCase()+' CHIẾN THẮNG';$('overlay').style.display='flex';$('overlay').innerHTML='';const tag=document.createElement('span');tag.className='eyebrow';tag.textContent='KẾT QUẢ TRẬN ĐẤU';const h=document.createElement('h2');h.textContent=title;const p=document.createElement('p');p.textContent=duel.fighters.map(f=>`${f.name}: ${f.damage} sát thương · ${f.beams} chưởng · ${f.dodges} lần lướt`).join(' / ');const btn=document.createElement('button');btn.textContent='↻ Xem lại cùng seed';btn.onclick=()=>{reset();toggle();};$('overlay').append(tag,h,p,btn);}}
function circle(x,y,r,color,width=1){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();}
function floor(){const g=ctx.createLinearGradient(0,0,960,540);g.addColorStop(0,'#263a4b');g.addColorStop(1,'#142231');ctx.fillStyle=g;ctx.fillRect(0,0,960,540);
 // A stone platform floating above layered clouds.
 ctx.fillStyle='#526c7b18';for(let i=0;i<12;i++){ctx.beginPath();ctx.ellipse(i*100-50,510+(i%3)*14,140,33,0,0,7);ctx.fill();}
 ctx.save();ctx.beginPath();ctx.roundRect(36,74,888,420,12);ctx.clip();ctx.fillStyle='#34464e';ctx.fillRect(36,74,888,420);ctx.strokeStyle='#82918e16';ctx.lineWidth=1;for(let y=74;y<500;y+=42){ctx.beginPath();ctx.moveTo(36,y);ctx.lineTo(924,y);ctx.stroke();for(let x=36+(Math.round(y/42)%2)*70;x<924;x+=140){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x,y+42);ctx.stroke();}}
 ctx.strokeStyle='#c4b18136';ctx.lineWidth=2;ctx.strokeRect(53,90,854,385);circle(480,282,155,'#c4b18125',2);circle(480,282,135,'#c4b18114');ctx.beginPath();ctx.moveTo(480,90);ctx.lineTo(480,475);ctx.strokeStyle='#c4b18118';ctx.stroke();ctx.translate(480,282);ctx.rotate(Math.PI/4);ctx.strokeStyle='#c4b18128';ctx.strokeRect(-38,-38,76,76);ctx.restore();ctx.strokeStyle='#a1b0a14d';ctx.lineWidth=3;ctx.strokeRect(36,74,888,420);
 for(const x of [54,906])for(const y of [92,475]){ctx.fillStyle='#c0ad78';ctx.fillRect(x-4,y-4,8,8);}ctx.fillStyle='#a8b9c23a';ctx.font='9px Segoe UI';ctx.textAlign='center';ctx.fillText('T H E   S K Y   T E M P L E',480,457);}
// Presentation-only effects. Never read back into combat simulation.
function glow(x,y,r,color,alpha=.65){const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,color);g.addColorStop(1,color+'00');ctx.save();ctx.globalAlpha=alpha;ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2);ctx.restore();}
function bolt(x1,y1,x2,y2,phase,color,width=1.5){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(x1,y1);const dx=x2-x1,dy=y2-y1,d=Math.hypot(dx,dy)||1;for(let k=1;k<7;k++){const jitter=Math.sin(k*8.1+phase)*7;ctx.lineTo(x1+dx*k/7-dy/d*jitter,y1+dy*k/7+dx/d*jitter);}ctx.lineTo(x2,y2);ctx.stroke();}
function drawCharge(f){const blue=f.id==='goku',color=blue?'#4cdbff':'#bd68ff',p=Math.min(1,f.age/.65),x=f.x+f.actionX*28,y=f.y-28,t=visualClock;ctx.save();ctx.globalCompositeOperation='lighter';glow(x,y,32+p*25,color,.5);circle(x,y,8+p*13,color,2);ctx.fillStyle='#f3ffff';ctx.beginPath();ctx.arc(x,y,3+p*7,0,Math.PI*2);ctx.fill();
 if(blue){for(let j=0;j<12;j++){const u=(t*1.6+j/12)%1,angle=j*2.4+t,rr=12+(1-u)*55;ctx.globalAlpha=u*.85;ctx.fillStyle='#a5f1ff';ctx.beginPath();ctx.arc(x+Math.cos(angle)*rr,y+Math.sin(angle)*rr,1+u*2,0,7);ctx.fill();}ctx.globalAlpha=.6;ctx.strokeStyle=color;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(x,y,18+p*18,7+p*7,t*3,0,7);ctx.stroke();}
 else{ctx.globalAlpha=.8;for(let j=0;j<5;j++){const angle=j*1.256+t*2,rr=20+p*20;bolt(x+Math.cos(angle)*rr,y+Math.sin(angle)*rr,x+Math.cos(angle+.5)*8,y+Math.sin(angle+.5)*8,j+t*26,'#dc9cff');}circle(x,y,19+p*8,'#edc2ff',1);}
 ctx.restore();}
function drawShot(s,enhanced){ctx.save();ctx.translate(s.x,s.y-28);ctx.rotate(Math.atan2(s.vy,s.vx));const blue=s.id==='goku',color=blue?'#35d4ff':'#b555ff',t=visualClock;if(enhanced){ctx.globalCompositeOperation='lighter';glow(-18,0,56,color,.65);const tail=ctx.createLinearGradient(-125,0,22,0);tail.addColorStop(0,color+'00');tail.addColorStop(.75,color+'bb');tail.addColorStop(1,'#e9fbff');ctx.fillStyle=tail;ctx.beginPath();ctx.moveTo(-130,0);ctx.quadraticCurveTo(-55,-23,8,-19);ctx.quadraticCurveTo(38,0,8,19);ctx.quadraticCurveTo(-55,23,-130,0);ctx.fill();ctx.strokeStyle=blue?'#9bf2ff':'#edb6ff';ctx.lineWidth=2;for(let j=0;j<3;j++){ctx.beginPath();for(let k=0;k<=20;k++){const x=-105+k*6,y=Math.sin(k*.65+t*24+j*2.1)*(blue?4:9);if(k===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);}ctx.stroke();}if(!blue){bolt(-80,-14,20,5,t*30,'#f3cfff');bolt(-85,14,16,-5,t*31,'#f3cfff');}}
 else{ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(-25,0,53,15,0,0,7);ctx.fill();}ctx.fillStyle='#f5ffff';ctx.beginPath();ctx.ellipse(1,0,24,enhanced?9:8,0,0,7);ctx.fill();ctx.restore();}
function drawBurst(b){const p=1-b.life/b.max,color=b.id==='goku'?'#62dcff':'#c386ff',size=b.heavy?72:34;ctx.save();ctx.globalCompositeOperation='lighter';ctx.globalAlpha=(1-p)*.9;glow(b.x,b.y,size*(.35+p),color,.6);circle(b.x,b.y,6+p*size,color,(1-p)*4+.5);ctx.translate(b.x,b.y);ctx.strokeStyle='#f1fcff';ctx.lineWidth=b.heavy?3:2;for(let j=0;j<(b.heavy?12:7);j++){const angle=j*2.399;ctx.beginPath();ctx.moveTo(Math.cos(angle)*(5+p*size*.25),Math.sin(angle)*(5+p*size*.25));ctx.lineTo(Math.cos(angle)*(12+p*size),Math.sin(angle)*(12+p*size));ctx.stroke();}ctx.restore();}
function render(){ctx.save();if(shake>0){ctx.translate(Math.sin(last*.073)*shake,Math.cos(last*.091)*shake*.55);}floor();
 for(const f of duel.fighters){if(f.state==='beam'&&f.age<.65){const color=f.id==='goku'?'#61d8ff':'#c180ff';ctx.save();ctx.setLineDash([9,9]);ctx.strokeStyle=color+'70';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(f.x,f.y);ctx.lineTo(f.x+f.actionX*900,f.y+f.actionY*900);ctx.stroke();ctx.setLineDash([]);if($('vfx').checked)drawCharge(f);else circle(f.x+f.actionX*28,f.y-28,8+f.age*18,color,3);ctx.restore();}}
 if($('vfx').checked)for(const ghost of ghosts){const im=images[ghost.id];if(!im.complete||!im.naturalWidth)continue;ctx.save();ctx.globalAlpha=.30*Math.pow(ghost.life/.24,1.4);ctx.translate(ghost.x,ghost.y);ctx.scale(ghost.face<0?-1:1,1);ctx.filter=ghost.id==='goku'?'sepia(1) saturate(3) hue-rotate(150deg)':'sepia(1) saturate(3) hue-rotate(220deg)';ctx.drawImage(im,ghost.frame*320,3*224,320,224,-160*.86,-192*.86,320*.86,224*.86);ctx.restore();}

 for(const f of [...duel.fighters].sort((a,b)=>a.y-b.y)){ctx.fillStyle='#050c1880';ctx.beginPath();ctx.ellipse(f.x,f.y+4,30,10,0,0,7);ctx.fill();circle(f.x,f.y+3,29,f.id==='goku'?'#f5a55570':'#b68af570');const im=images[f.id],state=f.state==='beam'?'powerup':(hitFlash[f.id]>.08&&f.hp>0?'hurt':f.state);let frame=Math.floor(f.age*9)%6;if(state==='hurt')frame=1;if(['melee','dash','defeat'].includes(state))frame=Math.min(5,Math.floor((state==='defeat'?resultAge:f.age)*(state==='dash'?24:10)));const row=rows[state]??0;if(im.complete&&im.naturalWidth){ctx.save();ctx.translate(f.x,f.y);ctx.scale(f.face<0?-1:1,1);if(hitFlash[f.id]>0){ctx.filter='brightness(1.7) saturate(.6)';}ctx.drawImage(im,frame*320,row*224,320,224,-160*.86,-192*.86,320*.86,224*.86);ctx.restore();}else{ctx.fillStyle=f.id==='goku'?'orange':'#8556d8';ctx.fillRect(f.x-15,f.y-50,30,50);}if(f.state==='melee'&&f.age>.18&&f.age<.36){ctx.save();ctx.translate(f.x,f.y-25);ctx.rotate(Math.atan2(f.actionY,f.actionX));ctx.strokeStyle='#ffe3ab';ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,55,-.6,.6);ctx.stroke();if($('vfx').checked){ctx.globalAlpha=.4;ctx.lineWidth=12;ctx.stroke();ctx.globalAlpha=.8;ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,65,-.9,.3);ctx.stroke();}ctx.restore();}if($('debug').checked){circle(f.x,f.y,21,'#ffffff88');if(f.state==='melee')circle(f.x,f.y,98,'#ffb56a88');}}
 for(const shot of duel.shots)drawShot(shot,$('vfx').checked);
 if($('vfx').checked)for(const burst of bursts)drawBurst(burst);

 for(const e of fx){ctx.globalAlpha=Math.max(0,e.life/.65);ctx.font='bold 21px Segoe UI';ctx.textAlign='center';ctx.fillStyle='#fff1d8';ctx.fillText('−'+e.value,e.x,e.y-85-(.65-e.life)*45);circle(e.x,e.y-25,12+(.65-e.life)*50,'#ffdfa0',2);}ctx.globalAlpha=1;for(const p of particles){ctx.globalAlpha=p.life/p.max;ctx.fillStyle=p.color;ctx.fillRect(p.x-2,p.y-2,4,4);}ctx.globalAlpha=1;ctx.restore();}
function loop(t){const elapsed=Math.min((t-last)/1000||0,.1);last=t;
 const visualDt=(running?elapsed*Number($('speed').value):duel.result?elapsed:0);visualClock+=visualDt;for(const ghost of ghosts)ghost.life-=visualDt;ghosts=ghosts.filter(g=>g.life>0);for(const burst of bursts)burst.life-=visualDt;bursts=bursts.filter(b=>b.life>0);
 for(const e of fx)e.life-=visualDt;fx=fx.filter(e=>e.life>0);
 for(const key in hitFlash)hitFlash[key]=Math.max(0,hitFlash[key]-visualDt);
 shake=Math.max(0,shake-visualDt*35);
 for(const p of particles){p.x+=p.vx*visualDt;p.y+=p.vy*visualDt;p.life-=visualDt;}particles=particles.filter(p=>p.life>0);
 if(running){acc+=elapsed*Number($('speed').value);while(acc>=DT){duel.step();if(duel.tick%3===0&&$('vfx').checked)for(const f of duel.fighters)if(f.state==='dash')ghosts.push({id:f.id,x:f.x,y:f.y,face:f.face,frame:Math.min(5,Math.floor(f.age*24)),life:.24});if(ghosts.length>24)ghosts.splice(0,ghosts.length-24);acc-=DT;if(duel.result){acc=0;break;}}events();}
 else if(duel.result){resultAge+=elapsed;events();}
 update();render();requestAnimationFrame(loop);}reset();requestAnimationFrame(loop);

window.arena={get simulation(){return duel},reset,start:toggle};
